mapper.select:
/* saleson.shop.give.givepoint.GivePointMapper.getGivePointSum */ SELECT CNTR_AMT , CNTR_POINT , CNTR_USE_POINT , (CNTR_POINT - CNTR_USE_POINT) AS CNTR_BLCE_POINT FROM ( SELECT IFNULL(SUM(GC.CNTR_AMT), 0) AS CNTR_AMT -- 기부금액 , IFNULL(SUM(GC.CNTR_POINT), 0) AS CNTR_POINT -- 발생포인트 , ( SELECT IFNULL(SUM(CNTR_USE_POINT), 0) FROM G_CNTR_USE_POINT WHERE use_se_code ='1'
AND cntr_locgov_code = #{shLocgovCode}
AND year(point_use_de) between #{shCntrYearStart} and #{shCntrYearEnd}
) AS CNTR_USE_POINT FROM G_CNTR GC WHERE 1=1 AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND year(GC.CNTR_DE) between #{shCntrYearStart} and #{shCntrYearEnd}
AND GC.CNTR_LOCGOV_CODE = #{shLocgovCode}
) a

/* saleson.shop.give.givepoint.GivePointMapper.getGivePointListCount */ SELECT COUNT(*) AS CNT FROM( SELECT SUM(GC.CNTR_AMT) AS CNTR_AMT FROM G_CNTR GC, G_LOCGOV GL WHERE 1=1 AND GC.CNTR_LOCGOV_CODE = GL.LOCGOV_CODE AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND GL.LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) between #{shCntrYearStart} and #{shCntrYearEnd}
GROUP BY year(GC.CNTR_DE) , GL.UPPER_LOCGOV_CODE , GL.LOCGOV_CODE ) A

/* saleson.shop.give.givepoint.GivePointMapper.getGivePointList */ SELECT CNTR_YEAR ,UPPER_LOCGOV_CODE ,UPPER_LOCGOV_NM ,LOCGOV_CODE ,LOCGOV_NM ,CNTR_AMT ,CNTR_POINT ,CNTR_USE_POINT ,(CNTR_POINT-CNTR_USE_POINT) AS CNTR_BLCE_POINT FROM ( SELECT year(GC.CNTR_DE) as CNTR_YEAR , GL.UPPER_LOCGOV_CODE AS UPPER_LOCGOV_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GL.UPPER_LOCGOV_CODE AND CODE_TYPE = 'WDR' AND USE_YN = 'Y') AS UPPER_LOCGOV_NM , GL.LOCGOV_CODE AS LOCGOV_CODE , GL.LOCGOV_NM AS LOCGOV_NM , SUM(GC.CNTR_AMT) AS CNTR_AMT , SUM(GC.CNTR_POINT) AS CNTR_POINT , ( SELECT IFNULL(SUM(CNTR_USE_POINT), 0) FROM G_CNTR_USE_POINT a, G_LOCGOV b WHERE use_se_code ='1' AND a.cntr_locgov_code = b.locgov_code AND b.locgov_code = GL.locgov_code
AND cntr_locgov_code = #{shLocgovCode}
AND year(point_use_de) between #{shCntrYearStart} and #{shCntrYearEnd}
) AS CNTR_USE_POINT FROM G_CNTR GC, G_LOCGOV GL WHERE 1=1 AND GC.CNTR_LOCGOV_CODE = GL.LOCGOV_CODE AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND GL.LOCGOV_CODE = #{shLocgovCode}
AND year(GC.CNTR_DE) between #{shCntrYearStart} and #{shCntrYearEnd}
GROUP BY year(GC.CNTR_DE) , GL.UPPER_LOCGOV_CODE , GL.LOCGOV_CODE ORDER BY year(GC.CNTR_DE) DESC , GL.UPPER_LOCGOV_CODE , GL.LOCGOV_CODE ) A

/* saleson.shop.give.givepoint.GivePointMapper.getGivePointDetail */ SELECT CNTR_POINT , CNTR_USE_POINT , CNTR_POINT-CNTR_USE_POINT AS CNTR_BLCE_POINT FROM ( SELECT IFNULL(SUM(CNTR_POINT), 0) AS CNTR_POINT , ( SELECT IFNULL(SUM(CNTR_USE_POINT), 0) FROM G_CNTR_USE_POINT WHERE use_se_code ='1'
AND cntr_locgov_code = #{shLocgovCode}
) AS CNTR_USE_POINT FROM G_CNTR GC WHERE 1=1 AND year(GC.CNTR_DE) = DATE_FORMAT(NOW(), '%Y') AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND CNTR_LOCGOV_CODE = #{shLocgovCode}
) A

		/* saleson.shop.give.givepoint.GivePointMapper.getGivePointDetailSum */
		SELECT
			CNTR_POINT
			,	CNTR_USE_POINT
			,	CNTR_POINT - CNTR_USE_POINT AS CNTR_BLCE_POINT
		FROM
		(
	    SELECT
	        IFNULL(SUM(CNTR_POINT), 0) AS CNTR_POINT
	         , (
			    	SELECT IFNULL(SUM(A.CNTR_USE_POINT), 0)
			    	FROM G_CNTR_USE_POINT A, OP_USER B
			    	WHERE A.use_se_code ='1'
			    		AND A.user_id = B.user_id

						AND A.cntr_locgov_code = #{shLocgovCode}


				    	AND year(A.POINT_USE_DE) = #{shCntrYear}


				    	AND A.POINT_USE_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}


			        	AND B.USER_NAME = #{shUserName}

		      ) AS CNTR_USE_POINT
	    FROM G_CNTR GC, OP_USER OU
	    WHERE 1=1
	    AND GC.USER_ID = OU.USER_ID
	    AND GC.DELETE_AT = 'N'
	    and GC.cntr_sttus_code = '200'
        and GC.sttemnt_pay_de is not NULL

	    AND CNTR_LOCGOV_CODE = #{shLocgovCode}


	    AND year(GC.CNTR_DE) = #{shCntrYear}


	    AND CNTR_DE BETWEEN #{shCntrDeStart} AND #{shCntrDeEnd}


        AND OU.USER_NAME = #{shUserName}

		) A

		/* saleson.shop.give.givepoint.GivePointMapper.getGivePointDetailListCount */
	    SELECT COUNT(*)
		FROM g_cntr a
		INNER JOIN op_user b ON a.user_id = b.user_id
		WHERE 1 = 1
			AND a.delete_at = 'N'
			AND a.cntr_sttus_code = '200'
			AND year(a.sttemnt_pay_de) = #{shCntrYear}

            	AND a.cntr_locgov_code = #{shLocgovCode}


            	AND b.user_name = #{shUserName}

/* saleson.shop.give.givepoint.GivePointMapper.getGivePointDetailList */ SELECT a.sttemnt_pay_de , a.elctrn_pay_no , a.login_id , a.user_name , a.cntr_amt , a.cntr_point , a.cntr_use_point , a.cntr_point - cntr_use_point as cntr_blce_point FROM ( SELECT a.sttemnt_pay_de , a.elctrn_pay_no , a.login_id AS login_id , CASE WHEN user_name IS NULL THEN '탈퇴회원' ELSE a.user_name END AS user_name , a.cntr_amt , a.cntr_point , (SELECT IFNULL(sum(cntr_use_point), 0) FROM g_cntr_use_point c WHERE c.cntr_sn = a.cntr_sn AND year(c.point_use_de) = #{shCntrYear}) as cntr_use_point FROM ( SELECT a.cntr_sn , a.sttemnt_pay_de , a.elctrn_pay_no , a.user_id , b.login_id , b.user_name , IFNULL(a.cntr_amt, 0) AS cntr_amt , IFNULL(a.cntr_point, 0) AS cntr_point FROM g_cntr a INNER JOIN op_user b ON a.user_id = b.user_id WHERE 1 = 1 AND a.delete_at = 'N' AND a.cntr_sttus_code = '200' AND year(a.sttemnt_pay_de) = #{shCntrYear}
AND a.cntr_locgov_code = #{shLocgovCode}
AND b.user_name = #{shUserName}
) a ) a ORDER BY sttemnt_pay_de desc, user_name
